func (lr *LogisticRegression) Predict(features []float64) float64 {
    logit := 0.0
    for i := 0; i < lr.NumFeatures; i++ {
        logit += lr.Weights[i] * features[i]
    }
    return 1.0 / (1.0 + math.Exp(-logit))
