            label := labels[i]
            predicted := lr.Predict(featureVector)
            for j := 0; j < lr.NumFeatures; j++ {
                gradient := float64(label-predicted) * featureVector[j]
                lr.Weights[j] += lr.LearningRate * gradient
            }
        }
    }
}
func main() {
    data := [][]float64{
        {30.0, 50000.0, 1.0},
        {45.0, 70000.0, 0.0},
        {25.0, 40000.0, 1.0},
    }
    labels := []int{1, 0, 1}
    lr := &LogisticRegression{Weights: []float64{0.0, 0.0, 0.0}, LearningRate: 0.1, NumFeatures: 3}
    lr.Train(data, labels, 1000)
    input := []float64{35.0, 60000.0, 1.0}
    probability := lr.Predict(input)
    fmt.Printf("The probability of an event occurring within the next 30 days for a person who is %v years old, has an income of $%v, and lives in location %v is %v\n", input[0], input[1], input[2], probability)
}
```
In this example, we have trained the logistic regression model using the provided data and labels, with 1000 iterations. The input data for prediction is {35.0, 60000.0, 1.0}, which represents a person who is 35 years old, has an income of $60,000, and lives in location 1. The Predict function will return a value between 0 and 1, representing the probability of the event occurring within the next 30 days for this person.

