            System.out.println("Dependent clause: " + clauses[0]);
            System.out.println("Independent clause: " + clauses[1]);
        } else {
            System.out.println("The sentence is a compound-complex sentence.");
            System.out.println("Dependent clause 1: " + clauses[0]);
            System.out.println("Independent clause: " + clauses[1]);
            System.out.println("Dependent clause 2: " + clauses[2]);
        }
    }
}
