                            "To light our way and bring us hope within."};
        Console.WriteLine("My Petrarchan sonnet based on the " + sun + ":\n");
        for (int i = 0; i < octave.Length; i++)
        {
            Console.WriteLine(octave[i]);
        }
        Console.WriteLine();
        Console.WriteLine("But now the time has come to change my tune,");
        Console.WriteLine("And with a volta end this first half soon.");
        Console.WriteLine();
        for (int i = 0; i < sestet.Length; i++)
        {
            Console.WriteLine(sestet[i]);
        }
        Console.WriteLine("\nEnd of poem.");
    }
}
```
