   if (n <= 1) return false;
   for (int i = 2; i < n; i++) {
      if (n % i == 0) return false;
   }
   return true;
}
int main() {
   int x;
   cin >> x;
   int nextPrime = x + 1;
   while (!isPrime(nextPrime)) {
      nextPrime++;
   }
   cout << nextPrime << endl;
   return 0;
}
